         * State the detector leans toward but has not committed to.
         */pending: MotionState?, 
        /**
         * When `pending` started, in ms.
         */pendingSince: Double?, 
        /**
         * Latest OS activity class, if the latest input was an activity sample.
         */activity: ActivityKind?) {
